import{_ as s,o as i,c as e,a3 as t}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"快速开始 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/guide/quick-start"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/guide/quick-start"}]]},"headers":[],"relativePath":"zh/clice/guide/quick-start.md","filePath":"zh/clice/guide/quick-start.md","lastUpdated":1794738697000}'),l={name:"zh/clice/guide/quick-start.md"};function n(h,a,p,o,c,d){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="quick-start" tabindex="-1"><span id="快速开始" class="heading-alias"></span>快速开始 <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><h2 id="editor-plugins" tabindex="-1"><span id="编辑器插件" class="heading-alias"></span>编辑器插件 <a class="header-anchor" href="#editor-plugins" aria-label="Permalink to &quot;编辑器插件&quot;">​</a></h2><p>clice 实现了<a href="https://microsoft.github.io/language-server-protocol" target="_blank" rel="noreferrer">语言服务器协议</a>。任何支持该协议的编辑器都可与 clice 配合，提供 <code>code completion</code>、<code>diagnostics</code>、<code>hover</code>、<code>semantic highlighting</code> 等功能。</p><p>除标准协议外，clice 还支持若干协议扩展。为获得更完整的集成体验，建议使用专用的 clice 插件。</p><p>各编辑器的配置说明见<a href="./editors">编辑器设置</a>：Visual Studio Code、Neovim 和 Zed 提供官方插件，使用通用 LSP 客户端的编辑器（Helix、Emacs、Sublime Text、Kate、Vim）则提供配置片段。</p><h2 id="installation" tabindex="-1"><span id="安装" class="heading-alias"></span>安装 <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;安装&quot;">​</a></h2><h3 id="download-prebuilt-binary" tabindex="-1"><span id="下载预编译二进制文件" class="heading-alias"></span>下载预编译二进制文件 <a class="header-anchor" href="#download-prebuilt-binary" aria-label="Permalink to &quot;下载预编译二进制文件&quot;">​</a></h3><p>从 <a href="https://github.com/clice-io/clice/releases" target="_blank" rel="noreferrer">Releases</a> 页面下载最新二进制文件。</p><h3 id="build-from-source" tabindex="-1"><span id="从源码构建" class="heading-alias"></span>从源码构建 <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h3><p>详细步骤参见<a href="./build">从源码构建</a>。</p><h2 id="project-setup" tabindex="-1"><span id="项目配置" class="heading-alias"></span>项目配置 <a class="header-anchor" href="#project-setup" aria-label="Permalink to &quot;项目配置&quot;">​</a></h2><p>要让 clice 正确理解代码（例如定位头文件），需要提供 <code>compile_commands.json</code> 文件，即<a href="https://clang.llvm.org/docs/JSONCompilationDatabase.html" target="_blank" rel="noreferrer">编译数据库</a>。编译数据库记录每个源文件的编译选项。</p><p>默认情况下，clice 会加载项目根目录及其直接子目录（如 <code>build/</code>）中的每一份 <code>compile_commands.json</code>，并在打开某个文件时加载该文件到项目根目录之间各级目录中的编译数据库，因此目录树深处的数据库，会在其所在目录或更深层目录中的文件首次打开时加载。带有独立 <code>clice.toml</code> 或 <code>.clice/config.toml</code> 的子目录视为独立项目，外层项目绝不会加载它的数据库。只要任意规则设置了 <code>compile_commands</code> 或 <code>default_command</code>，这项自动发现就会关闭。如何在 <code>clice.toml</code> 中指定编译数据库、如何编译没有数据库条目的文件，参见<a href="./config-guide#compile-commands">配置指南</a>。</p><h3 id="cmake" tabindex="-1">CMake <a class="header-anchor" href="#cmake" aria-label="Permalink to &quot;CMake&quot;">​</a></h3><p>配置时添加 <code>-DCMAKE_EXPORT_COMPILE_COMMANDS=ON</code>：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_EXPORT_COMPILE_COMMANDS=ON</span></span></code></pre></div><p>这会在 <code>build</code> 目录中生成 <code>compile_commands.json</code>。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>此选项仅适用于 Makefile 和 Ninja 生成器。使用其他生成器（如 Visual Studio）时，请改用下方的替代方案。</p></div><h3 id="bazel" tabindex="-1">Bazel <a class="header-anchor" href="#bazel" aria-label="Permalink to &quot;Bazel&quot;">​</a></h3><p>使用 clice 的 Bazel registry 中的 <code>compdb</code> 模块。在项目中添加该 registry 与模块：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .bazelrc</span></span>
<span class="line"><span>common --registry=https://bazel.clice.io/</span></span>
<span class="line"><span>common --registry=https://bcr.bazel.build/</span></span></code></pre></div><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># MODULE.bazel</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bazel_dep(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;compdb&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">dev_dependency</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>随后在 <code>MODULE.bazel</code> 同级目录生成 <code>compile_commands.json</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bazel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @compdb//:refresh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output_groups=+compilation_prerequisites_INTERNAL_</span></span></code></pre></div><p>默认覆盖 <code>//...</code>；在 <code>--</code> 后追加目标可缩小范围。附加的输出组（output group）会构建编译命令需要读取但本身不会触发构建的产物：生成的头文件，以及 Bazel 用于暴露库头文件的 <code>_virtual_includes</code> 目录。若不加该输出组，这些头文件在其他目标构建它们之前都会缺失，所有包含它们的文件都会报找不到头文件。</p><h3 id="visual-studio" tabindex="-1">Visual Studio <a class="header-anchor" href="#visual-studio" aria-label="Permalink to &quot;Visual Studio&quot;">​</a></h3><p>在 Visual Studio（2019 16.1 及以上版本）中使用 CMake 项目时，在 <code>CMakeSettings.json</code> 中配置：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;configurations&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;x64-Debug&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;generator&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ninja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;buildRoot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${projectDir}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;cmakeCommandArgs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-DCMAKE_EXPORT_COMPILE_COMMANDS=ON&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>MSBuild 项目（<code>.vcxproj</code>）可使用 <a href="https://github.com/clice-io/catter" target="_blank" rel="noreferrer">catter</a> 生成编译数据库。</p><h3 id="makefile" tabindex="-1">Makefile <a class="header-anchor" href="#makefile" aria-label="Permalink to &quot;Makefile&quot;">​</a></h3><p>使用 <a href="https://github.com/rizsotto/Bear" target="_blank" rel="noreferrer">bear</a> 拦截编译命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bear</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre></div><p>在运行 <code>bear -- make</code> 前先执行 <code>make clean</code>，以确保捕获所有编译命令。</p><h3 id="meson" tabindex="-1">Meson <a class="header-anchor" href="#meson" aria-label="Permalink to &quot;Meson&quot;">​</a></h3><p>Meson 会自动生成编译数据库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meson</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h3 id="xmake" tabindex="-1">Xmake <a class="header-anchor" href="#xmake" aria-label="Permalink to &quot;Xmake&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile_commands</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lsp=clangd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>也可以配置 Xmake 的 VS Code 扩展自动生成编译数据库：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xmake.compileCommandsDirectory&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;build&quot;</span></span></code></pre></div><h3 id="others" tabindex="-1"><span id="其他构建系统" class="heading-alias"></span>其他构建系统 <a class="header-anchor" href="#others" aria-label="Permalink to &quot;其他构建系统&quot;">​</a></h3><p>使用其他构建系统时，可借助 <a href="https://github.com/clice-io/catter" target="_blank" rel="noreferrer">catter</a>——它采用伪编译器方案，适用于任意构建系统。</p><h2 id="pre-build-the-index-optional" tabindex="-1"><span id="预构建索引-可选" class="heading-alias"></span>预构建索引（可选） <a class="header-anchor" href="#pre-build-the-index-optional" aria-label="Permalink to &quot;预构建索引（可选）&quot;">​</a></h2><p>在编辑器中打开项目时，后台索引会自动启动。大型项目也可以提前在命令行构建索引：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span></span></code></pre></div><p>构建过程支持断点续跑——按 Ctrl-C 中断时会保存当前进度，下次运行将从中断处继续，而无需重新开始。运行 <code>clice index stats --workspace /path/to/project</code> 可查看持久化索引的统计内容。如何缩短首次索引的时间，参见<a href="./config-guide#a-faster-first-index">加快首次索引</a>。</p>`,46)])])}const g=s(l,[["render",n]]);export{k as __pageData,g as default};
